<script lang="ts">
  import type { ParsedRaceCapture, RaceRunner } from '@/lib/race/race-capture-parser';
  import { analyzeMultiRace } from '@/lib/race/multi-race-analysis';
  import { formatRaceTime, runningStyleName } from '@/lib/race/race-display';
  import Tabs from '@/components/Tabs.svelte';
  import TextField from '@/components/TextField.svelte';
  import SelectField from '@/components/SelectField.svelte';
  import DataTable from '@/components/DataTable.svelte';
  import ChartFrame from '@/components/ChartFrame.svelte';
  import LazyEChartsSurface from '@/components/charts/LazyEChartsSurface.svelte';
  import Artwork from '@/components/Artwork.svelte';
  import RaceSkill from './RaceSkill.svelte';
  import Button from '@/components/Button.svelte';
  import Dialog from '@/components/Dialog.svelte';
  import {virtualScroll,type VirtualRange} from '@/lib/virtual-scroll';
  import EmptyState from '@/components/EmptyState.svelte';
  import RunnerBuild from './RunnerBuild.svelte';
  import { histogram, percent, portrait, rate, score, styleColors, teamBuilds } from './analysis-view';
  import { theme } from '@/stores/theme';
  let { captures, skillNames = new Map<number,string>(), view = $bindable('overview'), navigation = true, onreplay, onlobby }: {
    captures: ParsedRaceCapture[]; skillNames?: Map<number,string>; view?: string; navigation?: boolean;
    onreplay?: (index:number)=>void; onlobby?: (members:RaceRunner[])=>void;
  } = $props();
  const analysis=$derived(analyzeMultiRace(captures));
  const entries=$derived(captures.flatMap((c,race)=>c.runners.map(runner=>({runner,race}))));
  const winners=$derived(entries.filter(e=>e.runner.result?.finishOrder===1));
  const teams=$derived(teamBuilds(captures));
  let search=$state(''),style=$state('all'),uma=$state(''),sort=$state('wins'),minimum=$state('0'),teamRange=$state<VirtualRange>({start:0,end:0}),scorePopulation=$state('all'),skill=$state(''),detail=$state<RaceRunner[]>(),detailTitle=$state(''),selectedRace=$state(0);
  const tabs=[{id:'overview',label:'Overview'},{id:'strategies',label:'Strategy Analysis'},{id:'characters',label:'Uma Analysis'},{id:'teams',label:'Teams & Builds'},{id:'skills',label:'Skill Analysis'},{id:'hp',label:'HP & Last Spurt'}];
  $effect(()=>{captures;detail=undefined;});
  const ink=$derived($theme==='dark'?'#abb4c3':'#566071');
  function chart(series:unknown[],xAxis:Record<string,unknown>,yAxis:Record<string,unknown>={type:'value'},extra:Record<string,unknown>={}) {
    return {animation:false,textStyle:{color:ink},tooltip:{trigger:'axis'},grid:{left:48,right:24,top:24,bottom:45},xAxis:{nameLocation:'middle',nameGap:30,axisLabel:{fontSize:10,color:ink},splitLine:{lineStyle:{color:ink,opacity:.12}},...xAxis},yAxis:{axisLabel:{fontSize:10,color:ink},splitLine:{lineStyle:{color:ink,opacity:.12}},...yAxis},series,...extra};
  }
  const times=$derived(histogram(winners.map(e=>e.runner.result!.finishTime)));
  const scores=$derived(histogram((scorePopulation==='winners'?winners:entries).map(e=>score(e.runner)).filter(n=>n>0)));
  const feats=$derived.by(()=>{
    if(!winners.length)return [];
    const time=[...winners].sort((a,b)=>a.runner.result!.finishTime-b.runner.result!.finishTime);
    const ranked=winners.filter(e=>score(e.runner)>0).sort((a,b)=>score(b.runner)-score(a.runner));
    return [{label:'Fastest win',entry:time[0]!,value:formatRaceTime(time[0]!.runner.result!.finishTime)},{label:'Slowest win',entry:time.at(-1)!,value:formatRaceTime(time.at(-1)!.runner.result!.finishTime)},...(ranked.length?[{label:'Highest rated winner',entry:ranked[0]!,value:score(ranked[0]!.runner).toLocaleString()},{label:'Lowest rated winner',entry:ranked.at(-1)!,value:score(ranked.at(-1)!.runner).toLocaleString()}]:[])];
  });
  const styles=$derived(analysis.strategies.filter(r=>r.strategy>0));
  const characters=$derived(analysis.characters.filter(r=>rate(r.races,entries.length)>=Number(minimum)).sort((a,b)=>sort==='popularity'?b.races-a.races:rate(b.wins,b.races)-rate(a.wins,a.races)));
  const selectedCharacter=$derived(analysis.characters.find(r=>r.key===uma)??analysis.characters[0]);
  const filteredTeams=$derived(teams.filter(team=>team.members.some(r=>(!uma||String(r.cardId??r.name)===uma)&&(style==='all'||String(r.result?.runningStyle)===style))&&(team.trainer+' '+team.members.map(r=>r.name).join(' ')).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='appearances'?b.appearances-a.appearances:rate(b.wins,b.appearances)-rate(a.wins,a.appearances)));
  const compositions=$derived.by(()=>{
    const groups=new Map<string,{key:string;styles:number[];appearances:number;wins:number}>();
    for(const team of teams){const styles=team.members.map(r=>r.result?.runningStyle??0).sort();const key=styles.join('-'),row=groups.get(key)??{key,styles,appearances:0,wins:0};row.appearances+=team.appearances;row.wins+=team.wins;groups.set(key,row);}
    return [...groups.values()].sort((a,b)=>rate(b.wins,b.appearances)-rate(a.wins,a.appearances));
  });
  const selectedSkill=$derived(analysis.skills.find(r=>String(r.skillId)===skill)??analysis.skills[0]);
  const distances=$derived(histogram(selectedSkill?.activationDistances??[],16));
  function inspect(members:RaceRunner[],title:string,race:number){detail=members;detailTitle=title;selectedRace=race;}
  function findTeams(card:string,selectedStyle='all'){uma=card;style=selectedStyle;search='';view='teams';}
  function representatives(id:number){return analysis.characters.map(r=>({...r,entries:analysis.entries.filter(e=>e.charaKey===r.key&&e.strategy===id)})).filter(r=>r.entries.length).sort((a,b)=>b.entries.length-a.entries.length).slice(0,4);}
</script>
{#if navigation}<Tabs items={tabs} bind:value={view} label="Race statistics" controls="race-statistics-panel" variant="underline"/>{/if}
<div id="race-statistics-panel" class="analysis" role="tabpanel" aria-label={tabs.find(t=>t.id===view)?.label??view}>
{#if view==='overview'}
  <div class="metrics">{#each [{label:'Races analysed',value:captures.length,detail:captures[0]?.raceType??'Race captures'},{label:'Runner entries',value:entries.length,detail:analysis.characters.length+' different Umas'},{label:'Team builds',value:teams.length,detail:teams.reduce((n,t)=>n+t.appearances,0)+' team appearances'},{label:'Skill activations',value:analysis.skills.reduce((n,s)=>n+s.activations,0),detail:analysis.skills.length+' learned skills'}] as metric}<div><span>{metric.label}</span><strong>{metric.value.toLocaleString()}</strong><small>{metric.detail}</small></div>{/each}</div>
  <div class="overview"><div class="stack">
    <ChartFrame plain surface id="winning-times" title="Winning time distribution" description="The spread of race-winning finish times."><LazyEChartsSurface height={230} label="Winning time distribution" option={chart([{type:'bar',data:times.counts,itemStyle:{color:'#69b7ee',borderRadius:[3,3,0,0]}}],{type:'category',data:times.labels.map(value=>formatRaceTime(value,2)),axisLabel:{rotate:25}})}/></ChartFrame>
    <ChartFrame plain surface id="score-distribution" title="Score distribution" state={scores.counts.length?'ready':'empty'} emptyDetail="Training scores were not included in these captures.">
      {#snippet titleActions()}<Tabs items={[{id:'all',label:'All runners'},{id:'winners',label:'Winners'}]} bind:value={scorePopulation} label="Score population" variant="underline"/>{/snippet}
      <LazyEChartsSurface height={210} label="Training score distribution" option={chart([{type:'bar',data:scores.counts,itemStyle:{color:'#7bc8a0'}}],{type:'category',data:scores.labels.map(n=>(n/1000).toFixed(1)+'k')})}/>
    </ChartFrame>
  </div><div class="highlights">{#each feats as feat}<section class="panel feat"><span class="eyebrow">{feat.label}</span><strong class="feature-value">{feat.value}</strong><RunnerBuild runner={feat.entry.runner}/><Button size="sm" variant="ghost" onclick={()=>inspect([feat.entry.runner],feat.label,feat.entry.race)}>Inspect build →</Button></section>{/each}</div></div>
  <div class="two-col"><ChartFrame plain surface id="gate-results" title="Gate performance" description="Win rate for each starting gate.">
    <LazyEChartsSurface height={230} label="Win rate by gate" option={chart([{type:'bar',data:Array.from({length:Math.max(0,...captures.map(r=>r.runners.length))},(_,i)=>({value:+rate(winners.filter(e=>e.runner.index===i).length,entries.filter(e=>e.runner.index===i).length).toFixed(1),itemStyle:{color:styleColors[i%4+1]}}))}],{type:'category',data:Array.from({length:Math.max(0,...captures.map(r=>r.runners.length))},(_,i)=>String(i+1)),name:'Gate'},{type:'value',name:'Win %'})}/>
  </ChartFrame><section class="panel"><header><h3>The field at a glance</h3><p>Compare population with the share of race wins.</p></header>{#each styles as row}<button class="style-summary" onclick={()=>view='strategies'}><i style:background={styleColors[row.strategy]}></i><span>{runningStyleName(row.strategy)}<small>{row.races} entries</small></span><div class="share-bars"><b style:width={rate(row.races,entries.length)+'%'} style:background={styleColors[row.strategy]}></b><b style:width={rate(row.wins,captures.length)+'%'} style:background={styleColors[row.strategy]}></b></div><strong>{percent(row.wins,captures.length)}<small>win share</small></strong></button>{/each}<p class="footnote">Upper bar: population · Lower bar: wins</p></section></div>
{:else if view==='strategies'}
  <div class="style-cards">{#each styles as row}<button class="style-card" style:--style-color={styleColors[row.strategy]} onclick={()=>findTeams('',String(row.strategy))}><span>{runningStyleName(row.strategy)}</span><strong>{percent(row.wins,row.races)}</strong><small>individual win rate · {row.races} entries</small><div class="mini-bar"><b style:width={rate(row.wins,captures.length)+'%'}></b></div><footer>{percent(row.races,entries.length)} field · {percent(row.wins,captures.length)} wins</footer></button>{/each}</div>
  <div class="two-col"><ChartFrame plain surface id="style-breakdown" title="Strategy breakdown" description="Population compared with the winners." legend={[{label:'Field share',color:'#69b7ee'},{label:'Win share',color:'#7bc8a0'}]}>
    <LazyEChartsSurface height={280} label="Strategy population and win share" option={chart([{name:'Field share',type:'bar',data:styles.map(r=>+rate(r.races,entries.length).toFixed(1)),itemStyle:{color:'#69b7ee'}},{name:'Win share',type:'bar',data:styles.map(r=>+rate(r.wins,captures.length).toFixed(1)),itemStyle:{color:'#7bc8a0'}}],{type:'category',data:styles.map(r=>runningStyleName(r.strategy,true))},{type:'value',name:'Share %'})}/>
  </ChartFrame><ChartFrame plain surface id="style-saturation" title="Strategy saturation" description="Win rate as more runners use the same style." legend={styles.map(r=>({label:runningStyleName(r.strategy,true),color:styleColors[r.strategy]!}))}>
    <LazyEChartsSurface height={280} label="Strategy saturation" option={chart(styles.map(r=>({name:runningStyleName(r.strategy),type:'line',symbolSize:7,itemStyle:{color:styleColors[r.strategy]},data:r.saturation.map(b=>[b.count,+rate(b.wins,b.races).toFixed(1)])})),{type:'value',min:1,max:Math.max(9,...captures.map(c=>c.runners.length)),minInterval:1,name:'In room'},{type:'value',name:'Win %'})}/>
  </ChartFrame></div>
  <section class="panel"><header><h3>Style representatives</h3><p>Select an Uma to find the teams using it.</p></header><div class="representatives">{#each styles as row}<div><h4 style:color={styleColors[row.strategy]}>{runningStyleName(row.strategy)}</h4>{#each representatives(row.strategy) as r}<button class="uma-row" onclick={()=>findTeams(r.key,String(row.strategy))}><Artwork src={portrait(Number(r.key))} alt="" size="sm"/><span>{r.name}<small>{r.entries.length} entries</small></span><strong>{percent(r.entries.filter(e=>e.finishOrder===1).length,r.entries.length)}<small>win rate</small></strong></button>{/each}</div>{/each}</div></section>
  <section class="panel"><header><h3>Team compositions</h3><p>Which combinations of strategies win together?</p></header><div class="composition-list">{#each compositions.slice(0,12) as row}<div class="composition"><div>{#each row.styles as id}<span class="style-pill" style:--style-color={styleColors[id]}>{runningStyleName(id,true)}</span>{/each}</div><span>{row.appearances} teams</span><div class="mini-bar"><b style:width={rate(row.wins,row.appearances)+'%'}></b></div><strong>{percent(row.wins,row.appearances)}</strong></div>{/each}</div></section>
{:else if view==='characters'}
  <div class="toolbar"><SelectField id="uma-minimum" label="Minimum field share" options={[{value:'0',label:'All Umas'},{value:'3',label:'At least 3%'},{value:'5',label:'At least 5%'}]} bind:value={minimum}/><SelectField id="uma-ranking" label="Rank by" options={[{value:'wins',label:'Win rate'},{value:'popularity',label:'Popularity'}]} bind:value={sort}/></div>
  <div class="uma-analysis"><section class="panel"><header><h3>Uma breakdown</h3><p>Select an Uma to explore its team combinations.</p></header><div class="ranking">{#each characters as r,i}<button class="uma-row" class:selected={selectedCharacter?.key===r.key} onclick={()=>uma=r.key}><span class="rank-index">{i+1}</span><Artwork src={portrait(Number(r.key))} alt="" size="sm"/><span>{r.name}<small>{r.races} entries · {percent(r.races,entries.length)} field</small><div class="mini-bar"><b style:width={rate(r.wins,r.races)*3+'%'}></b></div></span><strong>{percent(r.wins,r.races)}<small>{r.wins} wins</small></strong></button>{/each}</div></section>
    <div class="stack"><ChartFrame plain surface id="uma-popularity" title="Popularity vs. performance" description="Each point is an Uma. Bubble size shows appearances.">
      <LazyEChartsSurface height={340} label="Uma popularity and win rate" option={chart([{type:'scatter',symbolSize:(v:number[])=>Math.max(12,Math.sqrt(v[2]??1)*4),data:characters.map(r=>({name:r.name,value:[+rate(r.races,entries.length).toFixed(2),+rate(r.wins,r.races).toFixed(2),r.races],itemStyle:{color:r.key===selectedCharacter?.key?'#e8ad63':'#69b7ee',opacity:.8}}))}],{type:'value',name:'Field share %',nameLocation:'middle',nameGap:28},{type:'value',name:'Win %'},{tooltip:{trigger:'item'}})}/>
    </ChartFrame>{#if selectedCharacter}<section class="panel"><header class="selection-heading"><Artwork src={portrait(Number(selectedCharacter.key))} alt="" size="md"/><div><h3>{selectedCharacter.name}</h3><p>{selectedCharacter.wins} wins / {selectedCharacter.races} appearances</p></div><Button size="sm" variant="secondary" onclick={()=>findTeams(selectedCharacter.key)}>Find teams →</Button></header><h4>Winning partners</h4>{#each analysis.teams.filter(t=>t.members.some(m=>String(m.cardId)===selectedCharacter.key)).sort((a,b)=>b.wins-a.wins).slice(0,4) as team}<div class="partners"><div>{#each team.members as member}<Artwork src={portrait(member.cardId)} alt={member.name} size="sm"/>{/each}</div><span>{team.appearances} appearances</span><strong>{percent(team.wins,team.appearances)}</strong></div>{/each}</section>{/if}</div>
  </div>
{:else if view==='teams'}
  <div class="toolbar"><TextField id="cm-search" label="Uma or trainer" type="search" placeholder="Search teams and builds…" bind:value={search}/><SelectField id="team-style" label="Strategy" options={[{value:'all',label:'All strategies'},...[1,2,3,4].map(id=>({value:String(id),label:runningStyleName(id)}))]} bind:value={style}/><SelectField id="team-sort" label="Sort teams" options={[{value:'wins',label:'Team win rate'},{value:'appearances',label:'Most appearances'}]} bind:value={sort}/></div>
  <div class="section-heading"><p>{filteredTeams.length} team builds · Inspect stats, aptitudes, skills, and replays.</p>{#if uma}<Button variant="secondary" size="sm" onclick={()=>uma=''}>Clear Uma filter ×</Button>{/if}</div>
  <div class="team-grid" use:virtualScroll={{items:filteredTeams,estimate:600,searchText:t=>t.trainer+' '+t.members.map(r=>r.name).join(' '),onrange:r=>teamRange=r}}>{#each filteredTeams.slice(teamRange.start,teamRange.end) as team,i}<section data-virtual-index={teamRange.start+i} class="panel team-card"><header class="section-heading"><div><span class="eyebrow">TEAM {String(teamRange.start+i+1).padStart(2,'0')}</span><h3>{team.trainer}</h3></div><strong class="team-rate">{percent(team.wins,team.appearances)}<small>{team.wins} / {team.appearances} wins</small></strong></header><div class="team-members">{#each team.members as runner}<RunnerBuild {runner}/>{/each}</div><footer><Button variant="secondary" size="sm" onclick={()=>inspect(team.members,team.trainer,team.races[0]!)}>Inspect team</Button>{#if onlobby}<Button variant="ghost" size="sm" onclick={()=>onlobby?.(team.members)}>Add to lobby +</Button>{/if}</footer></section>{:else}<EmptyState icon="search" title="No matching teams" description="Clear the Uma filter or try another strategy or name."/>{/each}</div>
{:else if view==='skills'}
  <div class="two-col"><section class="panel"><header><h3>Skill activation overview</h3><p>Learned skills, successful activations, and repeat triggers.</p></header><div class="metrics compact"><div><span>Skills learned</span><strong>{analysis.skills.reduce((n,r)=>n+r.learned,0)}</strong></div><div><span>Activated runners</span><strong>{percent(analysis.skills.reduce((n,r)=>n+r.activatedRunners,0),analysis.skills.reduce((n,r)=>n+r.learned,0))}</strong></div></div><p class="footnote">Runner win rates describe correlation, not the skill’s causal effect.</p><SelectField id="skill-selection" label="Inspect activation locations" options={analysis.skills.map(r=>({value:String(r.skillId),label:skillNames.get(r.skillId)??('Skill '+r.skillId)}))} value={String(selectedSkill?.skillId??'')} onchange={v=>skill=v}/></section>
    <ChartFrame plain surface id="skill-locations" title="Where does it activate?" description={selectedSkill?skillNames.get(selectedSkill.skillId)??('Skill '+selectedSkill.skillId):'No activation events available'}><LazyEChartsSurface height={240} label="Skill activation distance" option={chart([{type:'bar',data:distances.counts,itemStyle:{color:'#d194df'}}],{type:'category',data:distances.labels.map(n=>Math.round(n)+'m'),axisLabel:{rotate:25}},{type:'value',name:'Activations'})}/></ChartFrame>
  </div><TextField id="analysis-search" label="Filter skills" type="search" bind:value={search} placeholder="Search learned skills…"/>
  <DataTable plain caption="Skill Analysis" columns={[{key:'name',label:'Skill'},{key:'learned',label:'Learned',numeric:true},{key:'activated',label:'Activation rate',numeric:true},{key:'double',label:'Double procs',numeric:true},{key:'winrate',label:'Runner win rate',numeric:true}]} rows={analysis.skills.map(r=>({id:r.skillId,name:skillNames.get(r.skillId)??('Skill '+r.skillId),learned:r.learned,activated:percent(r.activatedRunners,r.learned),double:r.doubleProcRaces,winrate:percent(r.wins,r.learned)})).filter(r=>r.name.toLowerCase().includes(search.toLowerCase()))}>{#snippet cell(row,column)}{#if column.key==='name'}<button class="skill-select" onclick={()=>skill=String(row.id)}><RaceSkill id={Number(row.id)} name={String(row.name)}/></button>{:else}{row[column.key]}{/if}{/snippet}</DataTable>
{:else if view==='hp'}
  <div class="two-col">{#each ['hp','spurt'] as kind}<ChartFrame plain surface id={'runner-'+kind} title={kind==='hp'?'HP remaining at the finish':'Last-spurt timing'} description="Your runners only."><LazyEChartsSurface height={320} label={kind==='hp'?'Average remaining HP by Uma':'Last spurt starting distance'} option={chart([{type:'bar',data:analysis.hp.map(r=>kind==='hp'?Math.round(r.finishHpTotal/r.races):r.lastSpurtRaces?Math.round(r.lastSpurtDistanceTotal/r.lastSpurtRaces):null),itemStyle:{color:kind==='hp'?'#7bc8a0':'#e8ad63'}}],{type:'category',data:analysis.hp.map(r=>r.name),axisLabel:{rotate:35}},{type:'value',name:kind==='hp'?'HP':'Distance (m)'})}/></ChartFrame>{/each}</div>
  <DataTable plain caption="HP & Last Spurt" columns={[{key:'name',label:'Your Uma'},{key:'entries',label:'Races',numeric:true},{key:'start',label:'Start HP',numeric:true},{key:'finish',label:'Finish HP',numeric:true},{key:'survival',label:'Finished with HP',numeric:true}]} rows={analysis.hp.map(r=>({name:r.name,entries:r.races,start:Math.round(r.startHpTotal/r.races),finish:Math.round(r.finishHpTotal/r.races),survival:percent(r.survived,r.races)}))}/>
{/if}
</div>
<Dialog open={Boolean(detail)} title={detailTitle} maxWidth={detail?.length===1?'520px':'1120px'} onclose={()=>detail=undefined}><div class="detail-builds" class:single={detail?.length===1}>{#each detail??[] as runner}<RunnerBuild {runner} {skillNames} expanded/>{/each}</div>{#snippet actions()}{#if onreplay}<Button variant="secondary" onclick={()=>{detail=undefined;onreplay?.(selectedRace);}}>View race replay</Button>{/if}{#if onlobby&&detail?.length===3}<Button onclick={()=>{onlobby?.(detail!);detail=undefined;}}>Add team to lobby</Button>{/if}{/snippet}</Dialog>
<style>
.analysis,.stack{display:grid;gap:20px;min-width:0}.metrics{background:var(--surface-1);border-radius:var(--radius-lg);display:grid;grid-template-columns:repeat(4,minmax(0,1fr));padding:8px 0 24px;border-bottom:1px solid var(--border-subtle)}.metrics>div{display:grid;gap:6px;padding:18px 22px}.metrics>div+div{border-left:1px solid var(--border-subtle)}.metrics span,.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--text-secondary)}.metrics strong{font-size:28px;letter-spacing:-.04em;font-variant-numeric:tabular-nums}small{display:block;font-size:10px;color:var(--text-secondary);font-weight:400}.overview{display:grid;grid-template-columns:1.15fr 1fr;gap:20px}.highlights{display:grid;grid-template-columns:1fr 1fr;gap:28px}.panel{min-width:0;padding:20px;background:var(--surface-1);border-radius:var(--radius-lg)}.panel>header{margin-bottom:16px}h3,h4,p{margin:0}h3{font-size:14px}h4{font-size:12px;margin-bottom:8px}p{font-size:12px;color:var(--text-secondary);line-height:1.6}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.feat{display:flex;flex-direction:column;gap:14px}.feature-value{font-size:24px;color:var(--accent-primary)}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:20px}.style-summary{display:grid;grid-template-columns:4px 125px 1fr 65px;gap:12px;align-items:center;width:100%;padding:12px 0;border:0;border-bottom:1px solid var(--border-subtle);background:none;color:var(--text-primary);text-align:left;cursor:pointer;font-size:12px}.style-summary i{height:28px;border-radius:2px}.style-summary strong{text-align:right;font-size:14px}.share-bars{display:grid;gap:5px}.share-bars b{height:6px;min-width:2px;border-radius:2px}.share-bars b:first-child{opacity:.35}.footnote{font-size:10px;margin:12px 0}.style-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.style-card{text-align:left;padding:18px;display:grid;gap:10px;border:0;background:transparent;color:var(--text-